mapper.select:
SELECT r.id, r.reporter_id, r.product_id, r.reason, r.description, r.status, r.handle_remark, r.create_time, u.nickname AS reporter_nickname, p.title AS product_title, p.cover_color AS product_cover_color FROM tb_report r LEFT JOIN tb_user u ON r.reporter_id = u.id LEFT JOIN tb_product p ON r.product_id = p.id
AND r.status = #{status}
ORDER BY r.create_time DESC, r.id DESC
